import { FigureStage } from '@/components/motion/figure-frame';
import {
  CHART_STROKE,
  CHART_STRUCTURE,
  CHART_TYPE,
  CHART_VIEW_WIDTH,
  ChartAxes,
  LegendSwatch,
  PointMarker,
  roleColour,
} from '@/components/motion/chart';
import {
  DEFAULT_DR_RANGE,
  DEFAULT_REAL_MU,
  DR_RANGE_MAX,
  DR_RANGE_MIN,
  MU_MAX,
  MU_MIN,
  MU_TRAIN,
  POINT_PEAK,
  POINT_SIGMA,
