              fill={CHART_STRUCTURE.labelSecondary}
            >
              tries without a fall
            </text>
            <g data-chart-axes="">
              <line
                x1={practiceX}
                x2={practiceX}
                y1={PLOT.bottom}
                y2={PLOT.bottom + CHART_STROKE.tickLength}
