            data-testid={ghost ? undefined : `fk-link-${i + 1}`}
            x1={sx(p)}
            y1={sy(p)}
            x2={sx(points[i + 1])}
            y2={sy(points[i + 1])}
            stroke={colour}
            strokeWidth={width}
            strokeDasharray={ghost ? CHART_STROKE.dash : undefined}
            strokeLinecap="round"
