    <g data-testid="fk-swing" data-chart-role="highlight">
      <path
        d={`M ${x0} ${y0} A ${f(r)} ${f(r)} 0 0 ${turn > 0 ? 0 : 1} ${x1} ${y1}`}
        fill="none"
        stroke={colour}
        strokeWidth={CHART_STROKE.trace}
        strokeLinecap="round"
      />
      <polygon points={head} fill={colour} />
    </g>
  );
