  const feet: DogFeet = [foot(18), foot(17), foot(21), foot(20)];
  const hipY = f(Math.min(...feet.map(([, y]) => y)) - 34);
  return <RobotDog rear={f(cellX(17) + 3)} front={f(cellX(20) + 3)} hipY={hipY} feet={feet} segment={21} />;

