      ))}
      {dashed ? (
        <rect
          x={x - gap}
          y={y - gap}
          width={FRAME_COLS * pitch + gap}
          height={FRAME_ROWS * pitch + gap}
          fill="none"
          stroke={roleColour(role)}
          strokeWidth={CHART_STROKE.reference}
          strokeDasharray={CHART_STROKE.dash}
