const SEGMENTS = 32;
function segments(cpuBound: boolean): { d: string; offset: number }[] {
  const at = (i: number) => {
    const envs = MIN_ENVS * (MAX_ENVS / MIN_ENVS) ** (i / SEGMENTS);
