/*
 * The figure frame (owner-approved figure standard, 10 October 2026).
 *
 * Every figure is a 1 px hairline box with no fill, no radius and no
 * shadow. Inside it, in reading order on the page: the controls, the
 * drawing, a hairline rule, then the caption block, which opens with
 * "Figure N." in ink and continues in muted 13 px sans. N counts the
 * figures of one page (one article), in document order, with a CSS
 * counter, so the served HTML, hydration and every lazy mount agree.
 *
 * The header keeps its place in the DOM (title and controls first, so the
 * figure-system check and assistive technology read the same structure);
 * it only stops being a box, and flex order lays the title out under the
 * rule as the start of the caption block.
 */
/* main and the article are size containers, and container-type implies
   style containment: a counter reset on the container itself does not
   reach inside it, so each nested figure would start its own count. A
   reset's scope covers the element's following siblings, so the count
   starts on the container's first rendered child (an unrendered script
   carries no counter) and runs through the article. */
:where(main, main article) > :not(script, style, template, link) {
  counter-reset: figure-number;
}

:where(main, main article) > :not(script, style, template, link) ~ * {
  counter-reset: none;
}

[data-figure-frame],
figure[data-figure-kind='photograph'],
figure[data-figure-kind='official-mark'] {
  /* The site's text, border and accent utilities resolve to the figure
     palette inside a figure, so every primitive and figure that paints
     through them repaints in ink, muted, hairlines and the one accent. */
  --color-text: var(--ink);
  --color-text-dim: var(--muted);
  --color-ink: var(--ink);
  --color-graphite: var(--chart-dark);
  --color-border: var(--line);
  --color-border-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-link: var(--ink);
  --color-focus: var(--ink);
  /* No panels behind figure text: a surface is the page ground itself, so
     it still masks a line it sits on; a selection is the rare inset; the
     highlight is the one accent, never the lime. */
  --color-surface: var(--paper, var(--color-paper));
  --color-surface-2: var(--paper, var(--color-paper));
  --color-selection: var(--paper-deep, var(--color-concrete));
  --color-highlight: var(--accent);
  counter-increment: figure-number;
  display: flex;
  flex-direction: column;
  margin-block: 36px 40px;
  border: 1px solid var(--line);
  border-radius: 0;
  background: none;
  box-shadow: none;
  padding: 24px 26px 18px;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}

