  const key = value.replace(/\s+/g, '').toUpperCase();
  for (const [name, colour] of paletteEntries(tokens)) {
    if (colour.replace(/\s+/g, '').toUpperCase() === key) return `var(--${name})`;
  }
  return BRAND_VAR_BY_HEX[value] ?? value;
}

